import java.time.LocalDate; public class Fatura implements Pagavel,Tributavel { private final String descricao; private final double valor; private final LocalDate vencimento; public Fatura(String d,double v,LocalDate dt){descricao=d;valor=v;vencimento=dt;} public double getValor(){return valor;} public String getDescricao(){return descricao;} public LocalDate getDataVencimento(){return vencimento;} public double calcularImposto(){return valor*0.17;} public String getTipoImposto(){return "ICMS";} }
